// === 渲染与交互 ===
(function(){
  function render(){
    document.querySelectorAll('.chinamap').forEach(function(box){
      var stage = box.getAttribute('data-stage');
      var svgns = 'http://www.w3.org/2000/svg';
      var svg = document.createElementNS(svgns,'svg');
      svg.setAttribute('viewBox','0 0 1000 800');
      svg.setAttribute('class','cmap-svg');
      var land = document.createElementNS(svgns,'path');
      land.setAttribute('d', CHINA_PATH);
      land.setAttribute('class','cmap-land');
      svg.appendChild(land);
      ['bj','sh','gz','sz','wh'].forEach(function(city){
        var p = CITY_POS[city];
        var g = document.createElementNS(svgns,'g');
        g.setAttribute('class','pin');
        g.setAttribute('transform','translate('+p[0]+','+p[1]+')');
        var pulse = document.createElementNS(svgns,'circle');
        pulse.setAttribute('class','pin-pulse'); pulse.setAttribute('r','14');
        var dot = document.createElementNS(svgns,'circle');
        dot.setAttribute('class','pin-dot'); dot.setAttribute('r','7');
        var label = document.createElementNS(svgns,'text');
        label.setAttribute('class','pin-label');
        label.setAttribute('x','13'); label.setAttribute('y','6');
        label.textContent = CITY_NAME[city];
        g.appendChild(pulse); g.appendChild(dot); g.appendChild(label);
        g.addEventListener('click', function(){ openCity(city, stage, g); });
        svg.appendChild(g);
      });
      box.appendChild(svg);
    });
  }
  // 课程匹配关键词
  var KW = {
    "1": ["数据标注","标注","内容审核","审核","AI","工具","新媒体","智能客服","视频","短视频","脚本","AI视频","客服","训练师","数据","标签","分类","清洗","质检","运营","直播","剪辑","电商","测试","文案","素材","内容","发布","平台","生成","批量","监控","场控","复盘","产品","商品","图文"],
    "2": ["大模型","LLM","RAG","Agent","工作流","Prompt","提示词","API","知识库","向量","检索","Dify","Coze","低代码","微调","部署","智能体","编排","业务","前后端","AI","产品","集成","系统","测试","数据分析","看板","可视化","自动化","脚本","架构","接口","联调","文档","运维"],
    "3": ["Agent","产品经理","架构","API","编排","智能体","产品路线","LLM","商业化","大模型","高并发","方案","架构设计","多模态","流程","指标","数据","优化","AI","商业","落地","顾问","运营","增长","团队","带领","解决方案","转型","交付","质量","用户","定价","策略"]
  };
  function calcMatch(job, stage){
    var duties = job.d || [];
    if (!duties.length) return 33;
    var keywords = KW[stage] || KW["1"];
    var hitCount = 0;
    duties.forEach(function(d){
      if (keywords.some(function(kw){ return d.indexOf(kw) !== -1; })) hitCount++;
    });
    var score = Math.round((hitCount / duties.length) * 100);
    // 最低33%保证——只要是FDE相关岗位，至少三分之一匹配
    return Math.max(score, 33);
  }
  function isMatched(duty, stage){
    var keywords = KW[stage] || KW["1"];
    return keywords.some(function(kw){ return duty.indexOf(kw) !== -1; });
  }
  function getMatchTags(job, stage){
    var duties = job.d || [];
    var keywords = KW[stage] || KW["1"];
    // 长关键词优先，更精确
    var sorted = keywords.slice().sort(function(a,b){ return b.length - a.length; });
    var tags = [];
    for (var i = 0; i < duties.length && tags.length < 3; i++){
      for (var j = 0; j < sorted.length && tags.length < 3; j++){
        var kw = sorted[j];
        if (duties[i].indexOf(kw) === -1) continue;
        if (tags.indexOf(kw) !== -1) continue;
        // 如果已有更长的标签包含了这个短词，跳过
        var covered = tags.some(function(t){ return t.indexOf(kw) !== -1; });
        if (covered) continue;
        tags.push(kw);
        break;
      }
    }
    return tags;
  }
  function openCity(city, stage, g){
    var modal = document.getElementById('jobModal');
    var list = document.getElementById('jobList');
    document.getElementById('mCity').textContent = CITY_NAME[city];
    document.getElementById('mStage').textContent = STAGE_NAME[stage];
    list.innerHTML = '';
    document.querySelectorAll('.pin.active').forEach(function(x){ x.classList.remove('active'); });
    if (g) g.classList.add('active');
    var jobs = (JOBS[city] && JOBS[city][stage]) || [];
    jobs.forEach(function(job){
      var matchScore = calcMatch(job, stage);
      var card = document.createElement('div');
      card.className = 'jobc';
      // JD 条目，标注与课程匹配的项
      var jdItems = (job.d || []).map(function(d){
        var m = isMatched(d, stage);
        return '<div class="jd-item' + (m ? ' match' : '') + '"><span class="jd-dot">' + (m ? '&#10003;' : '·') + '</span>' + d + '</div>';
      }).join('');
      // 课程匹配技能标签（取2-3个）
      var matchTags = getMatchTags(job, stage);
      var tagHtml = matchTags.length
        ? '<div class="ben ben-match">' + matchTags.map(function(x){ return '<i>' + x + '</i>'; }).join('') + '</div>'
        : '';
      card.innerHTML = '<div class="jobc-top"><span class="jobc-t">' + job.t + '</span><span class="jobc-s">' + job.s + '</span></div>'
        + '<div class="mc-row"><span class="mc-label">课程匹配</span><span class="mc-pct">' + matchScore + '%</span><span class="mc-bar"><span class="mc-fill" style="width:' + matchScore + '%"></span></span></div>'
        + tagHtml
        + '<div class="jobc-meta">'
        + '<span>📍 ' + job.a + '</span>'
        + (job.edu ? '<span>🎓 ' + job.edu + '</span>' : '')
        + (job.exp ? '<span>💼 ' + job.exp + '</span>' : '')
        + '</div>'
        + '<div class="jobc-meta2">'
        + (job.co ? '<span>🏢 ' + job.co + '</span>' : '')
        + (job.sc ? '<span>👥 ' + job.sc + '</span>' : '')
        + '</div>'
        + '<div class="jobc-hint">▸ 点击展开，查看课程匹配详情</div>'
        + '<div class="jobc-d"><div class="jd-title">课程匹配详情</div>' + jdItems + '</div>';
      card.addEventListener('click', function(){
        card.classList.toggle('open');
        var hint = card.querySelector('.jobc-hint');
        if (hint) hint.style.display = card.classList.contains('open') ? 'none' : 'block';
      });
      list.appendChild(card);
    });
    if (!jobs.length){
      list.innerHTML = '<p style="color:var(--mut);font-size:13px;text-align:center;padding:14px">该城市本阶段暂无收录岗位</p>';
    }
    modal.classList.add('open');
    modal.setAttribute('aria-hidden','false');
    document.body.style.overflow = 'hidden';
  }
  function closeModal(){
    var modal = document.getElementById('jobModal');
    modal.classList.remove('open');
    modal.setAttribute('aria-hidden','true');
    document.body.style.overflow = '';
  }
  document.addEventListener('click', function(e){
    if (e.target && e.target.hasAttribute && e.target.hasAttribute('data-close')) closeModal();
  });
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape') closeModal(); });
  render();
})();
